module.exports = [{"id_kalimat":"amogenz_tasrif_001","teks_kalimat":"نَصَرَ","analysis":[{"id_lafadz":"amogenz_lafadz_001","word":"نَصَرَ","steps":{"1":{"question":"Apa Wazan dan Bab dari lafadz نَصَرَ dalam Tasrif Ishtilahi?","options":["Bab 1 (فَعَلَ - يَفْعُلُ)","Bab 2 (فَعَلَ - يَفْعِلُ)","Bab 3 (فَعَلَ - يَفْعَلُ)","Bab 4 (فَعِلَ - يَفْعَلُ)"],"correct":"Bab 1 (فَعَلَ - يَفْعُلُ)","explanation":"Lafadz نَصَرَ mengikuti wazan فَعَلَ dengan fi'il mudhori' يَنْصُرُ ber-wazan يَفْعُلُ, yang merupakan Bab 1 Thulathi Mujarrad menurut Matan Al-Bina'."},"2":{"question":"Bagaimana susunan lengkap Tasrif Ishtilahi dari lafadz نَصَرَ?","options":["نَصَرَ - يَنْصُرُ - نَصْرًا - فَهُوَ نَاصِرٌ - وَذَاكَ مَنْصُورٌ - أُنْصُرْ - لَا تَنْصُرْ - مَنْصَرٌ - مَنْصَرٌ - مِنْصَرٌ","نَصَرَ - يَنْصِرُ - نَصْرًا - فَهُوَ نَاصِرٌ - وَذَاكَ مَنْصُورٌ - اِنْصِرْ - لَا تَنْصِرْ - مَنْصِرٌ - مَنْصِرٌ - مِنْصَرٌ","نَصَرَ - يَنْصَرُ - نَصْرًا - فَهُوَ نَاصِرٌ - وَذَاكَ مَنْصُورٌ - اِنْصَرْ - لَا تَنْصَرْ - مَنْصَرٌ - مَنْصَرٌ - مِنْصَرٌ","نَصَرَ - يَنْصُرُ - نُصْرَانًا - فَهُوَ مَنْصُورٌ - وَذَاكَ نَاصِرٌ - أُنْصُرْ - لَا تَنْصُرْ - مَنْصَرٌ - مَنْصَرٌ - مِنْصَرٌ"],"correct":"نَصَرَ - يَنْصُرُ - نَصْرًا - فَهُوَ نَاصِرٌ - وَذَاكَ مَنْصُورٌ - أُنْصُرْ - لَا تَنْصُرْ - مَنْصَرٌ - مَنْصَرٌ - مِنْصَرٌ","explanation":"Tasrif Ishtilahi utuh untuk Bab 1 diawali Fi'il Madhi نَصَرَ, Mudhori' يَنْصُرُ, Masdar نَصْرًا, Isim Fa'il نَاصِرٌ, Isim Maf'ul مَنْصُورٌ, Fi'il Amr أُنْصُرْ, Fi'il Nahi لَا تَنْصُرْ, Isim Zaman/Makan مَنْصَرٌ, dan Isim Alat مِنْصَرٌ."},"3":{"question":"Bagaimana bentuk Tasrif Lughawi Fi'il Madhi dari lafadz نَصَرَ ketika bertemu dhomir Hum (هُمْ)?","options":["نَصَرُوا","نَصَرَا","نَصَرْنَ","نَصَرْتُمْ"],"correct":"نَصَرُوا","explanation":"Ketika fi'il madhi نَصَرَ bersambung dengan dhomir jama' mudzakkar ghaib (هُمْ), lam fi'il (ر) di-dhommah-kan dan ditambahkan Wawu Jama' serta Alif Tafriq sehingga menjadi نَصَرُوا."},"4":{"question":"Bagaimana bentuk Tasrif Lughawi Fi'il Mudhori' dari lafadz نَصَرَ ketika bertemu dhomir Antum (أَنْتُمْ)?","options":["تَنْصُرُونَ","يَنْصُرُونَ","تَنْصُرَانِ","تَنْصُرْنَ"],"correct":"تَنْصُرُونَ","explanation":"Untuk dhomir مخاطب جمع مذكر (أَنْتُمْ), fi'il mudhori' diawali huruf mudhoro'ah Ta' (تَـ) dan diakhiri Wawu Jama' serta Nun Tsubut (علامة الرفع), menjadi تَنْصُرُونَ."},"5":{"question":"Bagaimana pengaruh Bina' Shahih pada pola tasrifan lafadz نَصَرَ?","options":["Tidak terjadi perubahan huruf (i'lal/ibdal/idgham) karena seluruh huruf asal selamat dari huruf 'illat, hamzah, dan mudho'af","Terjadi penggabungan dua huruf sejenis (idgham) pada fi'il madhi","Terjadi pembuangan 'ain fi'il saat bersambung dhomir mutaharrik","Huruf lam fi'il diganti menjadi alif maqshurah"],"correct":"Tidak terjadi perubahan huruf (i'lal/ibdal/idgham) karena seluruh huruf asal selamat dari huruf 'illat, hamzah, dan mudho'af","explanation":"Lafadz نَصَرَ memiliki Bina' Shahih Salim, di mana fa', 'ain, dan lam fi'ilnya terbebas dari huruf 'illat (و, ا, ي), hamzah, maupun tadh'if (pengulangan huruf), sehingga harakat dan hurufnya tetap utuh tanpa i'lal."},"6":{"question":"Apa bentuk Fi'il Amr dan Fi'il Nahi dari lafadz نَصَرَ?","options":["أُنْصُرْ dan لَا تَنْصُرْ","اِنْصِرْ dan لَا تَنْصِرْ","اِنْصَرْ dan لَا تَنْصَرْ","نَصِّرْ dan لَا تُنَصِّرْ"],"correct":"أُنْصُرْ dan لَا تَنْصُرْ","explanation":"Fi'il Amr dibentuk dari mudhori' majzum (تَنْصُرْ) dengan membuang huruf mudhoro'ah dan menambah hamzah washol berharakat dhommah (sebab 'ain fi'il dhommah) menjadi أُنْصُرْ. Fi'il Nahi dibentuk dengan menambah Laa Nahiyah menjadi لَا تَنْصُرْ."},"7":{"question":"Apa bentuk Isim Fa'il dan Isim Maf'ul dari lafadz نَصَرَ?","options":["نَاصِرٌ dan مَنْصُورٌ","مُنْصِرٌ dan مُنْصَرٌ","نَصِيرٌ dan مَنْصَرٌ","نَاصِرٌ dan مُنَصَّرٌ"],"correct":"نَاصِرٌ dan مَنْصُورٌ","explanation":"Karena berasal dari Thulathi Mujarrad, Isim Fa'il dibuat mengikuti wazan فَاعِلٌ menjadi نَاصِرٌ, dan Isim Maf'ul mengikuti wazan مَفْعُولٌ menjadi مَنْصُورٌ."},"8":{"question":"Bagaimana bentuk Fi'il Mabni Majhul (pasif) dari lafadz نَصَرَ dalam Fi'il Madhi dan Fi'il Mudhori'?","options":["نُصِرَ (Madhi) dan يُنْصَرُ (Mudhori')","نَصَرَ (Madhi) dan يَنْصُرُ (Mudhori')","نُصِرَ (Madhi) dan يُنْصُرُ (Mudhori')","نُصَّرَ (Madhi) dan يُنَصَّرُ (Mudhori')"],"correct":"نُصِرَ (Madhi) dan يُنْصَرُ (Mudhori')","explanation":"Fi'il Madhi Majhul di-dhommah-kan huruf pertamanya dan di-kasrah-kan huruf sebelum akhir (نُصِرَ). Fi'il Mudhori' Majhul di-dhommah-kan huruf mudhoro'ah dan di-fathah-kan huruf sebelum akhir (يُنْصَرُ)."}}}]},{"id_kalimat":"amogenz_tasrif_002","teks_kalimat":"قَالَ","analysis":[{"id_lafadz":"amogenz_lafadz_002","word":"قَالَ","steps":{"1":{"question":"Apa Wazan asli dan Bab dari lafadz قَالَ dalam Tasrif Ishtilahi?","options":["Bab 1 (فَعَلَ - يَفْعُلُ) dengan wazan asal قَوَلَ - يَقْوُلُ","Bab 2 (فَعَلَ - يَفْعِلُ) dengan wazan asal قَيَلَ - يَقْيِلُ","Bab 4 (فَعِلَ - يَفْعَلُ) dengan wazan asal قَوِلَ - يَقْوَلُ","Bab 1 (فَعَلَ - يَفْعُلُ) dengan wazan asal قَالَ - يَقُولُ"],"correct":"Bab 1 (فَعَلَ - يَفْعُلُ) dengan wazan asal قَوَلَ - يَقْوُلُ","explanation":"Lafadz قَالَ tergolong Bab 1 Thulathi Mujarrad. Bentuk aslinya adalah قَوَلَ - يَقْوُلُ sebelum mengalami proses i'lal."},"2":{"question":"Bagaimana susunan lengkap Tasrif Ishtilahi dari lafadz قَالَ?","options":["قَالَ - يَقُولُ - قَوْلًا - فَهُوَ قَائِلٌ - وَذَاكَ مَقُولٌ - قُلْ - لَا تَقُلْ - مَقَالٌ - مَقَالٌ - مِقْوَلٌ","قَالَ - يَقِيلُ - قَيْلًا - فَهُوَ قَائِلٌ - وَذَاكَ مَقِيلٌ - قِلْ - لَا تَقِلْ - مَقِيلٌ - مَقِيلٌ - مِقْيَلٌ","قَالَ - يَقَالُ - قَوْلًا - فَهُوَ قَائِلٌ - وَذَاكَ مَقُولٌ - قَلْ - لَا تَقَالْ - مَقَالٌ - مَقَالٌ - مِقْوَلٌ","قَوَلَ - يَقْوُلُ - قَوْلًا - فَهُوَ قَاوِلٌ - وَذَاكَ مَقْوُولٌ - اُقْوُلْ - لَا تَقْوُلْ - مَقْوَلٌ - مَقْوَلٌ - مِقْوَلٌ"],"correct":"قَالَ - يَقُولُ - قَوْلًا - فَهُوَ قَائِلٌ - وَذَاكَ مَقُولٌ - قُلْ - لَا تَقُلْ - مَقَالٌ - مَقَالٌ - مِقْوَلٌ","explanation":"Deretan Tasrif Ishtilahi قَالَ yang sudah mengalami i'lal: قَالَ (Madhi), يَقُولُ (Mudhori'), قَوْلًا (Masdar), قَائِلٌ (Isim Fa'il), مَقُولٌ (Isim Maf'ul), قُلْ (Amr), لَا تَقُلْ (Nahi), مَقَالٌ (Zaman/Makan), مِقْوَلٌ (Isim Alat)."},"3":{"question":"Bagaimana bentuk Tasrif Lughawi Fi'il Madhi dari lafadz قَالَ ketika bertemu dhomir Tu/Ana (أَنَا)?","options":["قُلْتُ","قَالْتُ","قَوَلْتُ","قِلْتُ"],"correct":"قُلْتُ","explanation":"Saat lafadz قَالَ bertemu dhomir mutaharrik seperti Ana (أَنَا), lam fi'il di-sukun-kan (قَالْتْ). Terjadi pertemuan dua sukun (alif dan lam), sehingga alif dibuang. Fa' fi'il (ق) di-dhommah-kan (قُلْتُ) untuk menunjukkan bahwa huruf yang dibuang adalah Wawu."},"4":{"question":"Bagaimana bentuk Tasrif Lughawi Fi'il Mudhori' dari lafadz قَالَ ketika bertemu dhomir Hum (هُمْ)?","options":["يَقُولُونَ","يَقُولُنَّ","يَقُولَانِ","يَقُولْنَ"],"correct":"يَقُولُونَ","explanation":"Untuk dhomir هُمْ, Fi'il Mudhori' يَقُولُ ditambahi Wawu Jama' dan Nun Tsubut, menjadi يَقُولُونَ."},"5":{"question":"Bagaimana pengaruh Bina' Ajwaf Wawi pada pola tasrifan lafadz قَالَ?","options":["Huruf 'illat Wawu pada قَوَلَ bergerak dan berharakat fathah sesudah fathah, maka diganti menjadi Alif (قَالَ); sedangkan pada mudhori' harakat Wawu dipindah ke fa' fi'il","Huruf Wawu dibuang sepenuhnya di seluruh bentuk tasrifan","Huruf Wawu diganti Ya' pada bentuk Madhi maupun Mudhori'","Tidak ada pengaruh i'lal sama sekali"],"correct":"Huruf 'illat Wawu pada قَوَلَ bergerak dan berharakat fathah sesudah fathah, maka diganti menjadi Alif (قَالَ); sedangkan pada mudhori' harakat Wawu dipindah ke fa' fi'il","explanation":"Sesuai kaidah I'lal, Wawu hidup yang berada setelah fathah diganti Alif menjadi قَالَ. Pada mudhori' يَقْوُلُ, dhommah Wawu dipindah ke huruf shahih sebelumnya (Qaf) menjadi يَقُولُ."},"6":{"question":"Apa bentuk Fi'il Amr dan Fi'il Nahi dari lafadz قَالَ?","options":["قُلْ dan لَا تَقُلْ","أُقْوُلْ dan لَا تَقْوُلْ","قَالْ dan لَا تَقَالْ","قِلْ dan لَا تَقِلْ"],"correct":"قُلْ dan لَا تَقُلْ","explanation":"Bentuk dasar Amr dari يَقُولُ adalah تُقُولُ -> buang huruf mudhoro'ah dan sukunkan akhir -> تَقُولْ -> terjadi Iltiqa' As-Sakinain (Wawu sukun & Lam sukun), Wawu dibuang menjadi قُلْ. Nahi-nya adalah لَا تَقُلْ."},"7":{"question":"Apa bentuk Isim Fa'il dan Isim Maf'ul dari lafadz قَالَ?","options":["قَائِلٌ dan مَقُولٌ","قَاوِلٌ dan مَقْوُولٌ","قَيَّالٌ dan مَقِيلٌ","قَائِلٌ dan مَقْوُوٌّ"],"correct":"قَائِلٌ dan مَقُولٌ","explanation":"Pada Isim Fa'il قَاوِلٌ, Wawu diganti Hamzah karena jatuh setelah Alif Zaidah (قَائِلٌ). Pada Isim Maf'ul مَقْوُولٌ, terjadi transfer harakat dhommah Wawu pertama ke Qaf, lalu dibuang salah satu Wawu sukun untuk menghindari iltiqa' sakinain menjadi مَقُولٌ."},"8":{"question":"Bagaimana bentuk Fi'il Mabni Majhul (pasif) dari lafadz قَالَ dalam Fi'il Madhi dan Fi'il Mudhori'?","options":["قِيلَ (Madhi) dan يُقَالُ (Mudhori')","قُولَ (Madhi) dan يُقْوَلُ (Mudhori')","قُوِلَ (Madhi) dan يُقُولُ (Mudhori')","قِيلَ (Madhi) dan يُقُولُ (Mudhori')"],"correct":"قِيلَ (Madhi) dan يُقَالُ (Mudhori')","explanation":"Madhi Majhul asalnya قُوِلَ, harakat kasrah Wawu dipindah ke Qaf dan Wawu diganti Ya' menjadi قِيلَ. Mudhori' Majhul asalnya يُقْوَلُ, harakat fathah Wawu dipindah ke Qaf dan Wawu diganti Alif menjadi يُقَالُ."},"9":{"question":"Bagaimana penyesuaian bentuk Isim Makan/Zaman dari lafadz قَالَ menurut kaidah I'lal?","options":["Bentuk Isim Makan/Zaman dari lafadz قَالَ adalah مَقَالٌ, berasal dari مَقْوَلٌ yang harakat fathah Wawu-nya dipindah ke Qaf lalu Wawu diganti Alif","Bentuk Isim Makan/Zaman dari lafadz قَالَ adalah مَقُولٌ tanpa i'lal","Bentuk Isim Makan/Zaman dari lafadz قَالَ adalah مِقْوَالٌ","Bentuk Isim Makan/Zaman dari lafadz قَالَ adalah مَقِيلٌ"],"correct":"Bentuk Isim Makan/Zaman dari lafadz قَالَ adalah مَقَالٌ, berasal dari مَقْوَلٌ yang harakat fathah Wawu-nya dipindah ke Qaf lalu Wawu diganti Alif","explanation":"Wazan Isim Makan/Zaman Bab 1 adalah مَفْعَلٌ (مَقْوَلٌ). Harakat fathah pada Wawu dipindah ke Qaf yang sukun, lalu Wawu disesuaikan menjadi Alif karena berada setelah fathah, menghasilkan مَقَالٌ."}}}]},{"id_kalimat":"amogenz_tasrif_003","teks_kalimat":"دَعَا","analysis":[{"id_lafadz":"amogenz_lafadz_003","word":"دَعَا","steps":{"1":{"question":"Apa Wazan asli dan Bab dari lafadz دَعَا dalam Tasrif Ishtilahi?","options":["Bab 1 (فَعَلَ - يَفْعُلُ) dengan wazan asal دَعَوَ - يَدْعُوُ","Bab 2 (فَعَلَ - يَفْعِلُ) dengan wazan asal دَعَيَ - يَدْعِيُ","Bab 3 (فَعَلَ - يَفْعَلُ) dengan wazan asal دَعَعَ - يَدْعَعُ","Bab 4 (فَعِلَ - يَفْعَلُ) dengan wazan asal دَعِوَ - يَدْعَوُ"],"correct":"Bab 1 (فَعَلَ - يَفْعُلُ) dengan wazan asal دَعَوَ - يَدْعُوُ","explanation":"Lafadz دَعَا termasuk Bab 1 Thulathi Mujarrad (فَعَلَ - يَفْعُلُ) dengan bentuk asal دَعَوَ - يَدْعُوُ."},"2":{"question":"Bagaimana susunan lengkap Tasrif Ishtilahi dari lafadz دَعَا?","options":["دَعَا - يَدْعُو - دُعَاءً - فَهُوَ دَاعٍ - وَذَاكَ مَدْعُوٌّ - أُدْعُ - لَا تَدْعُ - مَدْعًى - مَدْعًى - مِدْعًى","دَعَا - يَدْعِي - دَعْوَةً - فَهُوَ دَاعِيٌ - وَذَاكَ مَدْعِيٌّ - اِدْعِ - لَا تَدْعِ - مَدْعًى - مَدْعًى - مِدْعًى","دَعَا - يَدْعَى - دُعَاءً - فَهُوَ دَاعٍ - وَذَاكَ مَدْعًى - اِدْعَ - لَا تَدْعَ - مَدْعًى - مَدْعًى - مِدْعًى","دَعَوَ - يَدْعُوُ - دَعْوًا - فَهُوَ دَاعِوٌ - وَذَاكَ مَدْعُوٌ - اُدْعُوُ - لَا تَدْعُوُ - مَدْعَوٌ - مَدْعَوٌ - مِدْعَوٌ"],"correct":"دَعَا - يَدْعُو - دُعَاءً - فَهُوَ دَاعٍ - وَذَاكَ مَدْعُوٌّ - أُدْعُ - لَا تَدْعُ - مَدْعًى - مَدْعًى - مِدْعًى","explanation":"Pola Tasrif Ishtilahi ter-i'lal dari lafadz دَعَا adalah: دَعَا (Madhi), يَدْعُو (Mudhori'), دُعَاءً (Masdar), دَاعٍ (Isim Fa'il), مَدْعُوٌّ (Isim Maf'ul), أُدْعُ (Amr), لَا تَدْعُ (Nahi), مَدْعًى (Zaman/Makan), مِدْعًى (Isim Alat)."},"3":{"question":"Bagaimana bentuk Tasrif Lughawi Fi'il Madhi dari lafadz دَعَا ketika bertemu dhomir Hum (هُمْ)?","options":["دَعَوْا","دَعَاوا","دَعُوا","دَعَيُوا"],"correct":"دَعَوْا","explanation":"Pada dhomir هُمْ, bentuk asal دَعَوُوا mengalami pembuangan (hazhaf) Wawu lam fi'il karena bertemu Wawu Jama' yang sukun, sehingga menjadi دَعَوْا (dengan fathah pada Ain fi'il untuk menunjukkan huruf yang terbuang)."},"4":{"question":"Bagaimana bentuk Tasrif Lughawi Fi'il Mudhori' dari lafadz دَعَا ketika bertemu dhomir Antum (أَنْتُمْ)?","options":["تَدْعُونَ","تَدْعُوُونَ","تَدْعَيُونَ","تَدْعُونَنَّ"],"correct":"تَدْعُونَ","explanation":"Fi'il Mudhori' asal تَدْعُوُونَ (dhomir أَنْتُمْ) mengalami penimbangan itsqal dan iltiqa' sakinain antar-Wawu, sehingga Wawu lam fi'il dibuang dan tersisa Wawu Jama' + Nun Tsubut menjadi تَدْعُونَ."},"5":{"question":"Bagaimana pengaruh Bina' Naqish Wawi pada pola tasrifan lafadz دَعَا?","options":["Lam fi'il berupa huruf 'illat Wawu diganti Alif pada Madhi (دَعَا) karena berharakat setelah Fathah, dan dhommah-nya ditiadakan pada Mudhori' (يَدْعُو) karena itsqal","Lam fi'il di-idgham-kan ke fa' fi'il","Fa' fi'il berupa huruf 'illat dibuang pada mudhori'","Tidak mempengaruhi harakat maupun penulisan sama sekali"],"correct":"Lam fi'il berupa huruf 'illat Wawu diganti Alif pada Madhi (دَعَا) karena berharakat setelah Fathah, dan dhommah-nya ditiadakan pada Mudhori' (يَدْعُو) karena itsqal","explanation":"Karena tergolong Bina' Naqish Wawi (lam fi'il berupa Wawu), pada madhi دَعَوَ Wawu diganti Alif (دَعَا). Pada mudhori' يَدْعُوُ dhommah di atas Wawu digugurkan karena terlalu berat diucapkan (itsqal)."},"6":{"question":"Apa bentuk Fi'il Amr dan Fi'il Nahi dari lafadz دَعَا?","options":["أُدْعُ dan لَا تَدْعُ","اِدْعِ dan لَا تَدْعِ","أُدْعُو dan لَا تَدْعُو","اِدْعَ dan لَا تَدْعَ"],"correct":"أُدْعُ dan لَا تَدْعُ","explanation":"Tanda jazam untuk Fi'il Amr dan Nahi pada Bina' Naqish adalah dengan membuang lam fi'il (huruf 'illat Wawu). Maka أُدْعُ (asal أُدْعُو) dan لَا تَدْعُ (asal لَا تَدْعُو)."},"7":{"question":"Apa bentuk Isim Fa'il dan Isim Maf'ul dari lafadz دَعَا?","options":["دَاعٍ dan مَدْعُوٌّ","دَاعِوٌ dan مَدْعُوٌَ","دَاعِيٌ dan مَدْعِيٌّ","مُدَّعٍ dan مُدَّعًى"],"correct":"دَاعٍ dan مَدْعُوٌّ","explanation":"Isim Fa'il asal دَاعِوٌ -> Wawu jadi Ya' (دَاعِيٌ) -> tanwin & ya' sukun -> Ya' dibuang dalam حالت رفع/جر menjadi دَاعٍ. Isim Maf'ul asal مَدْعُوٌوٌ (مَفْعُولٌ) -> di-idgham-kan dua Wawu menjadi مَدْعُوٌّ."},"8":{"question":"Bagaimana bentuk Fi'il Mabni Majhul (pasif) dari lafadz دَعَا dalam Fi'il Madhi dan Fi'il Mudhori'?","options":["دُعِيَ (Madhi) dan يُدْعَى (Mudhori')","دُعُوَا (Madhi) dan يُدْعُو (Mudhori')","دُعِيَ (Madhi) dan يُدْعِي (Mudhori')","دُعَا (Madhi) dan يُدْعَى (Mudhori')"],"correct":"دُعِيَ (Madhi) dan يُدْعَى (Mudhori')","explanation":"Madhi Majhul asal دُعِوَ -> Wawu diganti Ya' karena jatuh setelah kasrah menjadi دُعِيَ. Mudhori' Majhul asal يُدْعَوُ -> Wawu diganti Alif Maqshurah karena berharakat setelah Fathah menjadi يُدْعَى."},"9":{"question":"Bagaimana bentuk Isim Makan, Isim Zaman, dan Isim Alat dari lafadz دَعَا menurut kaidah I'lal?","options":["Isim Makan/Zaman adalah مَدْعًى dan Isim Alat adalah مِدْعًى (Wawu diganti Alif Maqshurah karena jatuh setelah fathah)","Isim Makan/Zaman adalah مَدْعُوٌ dan Isim Alat adalah مِدْعَاوٌ","Isim Makan/Zaman adalah مَدْعِىٌ dan Isim Alat adalah مِدْعَاعٌ","Isim Makan/Zaman adalah مَدْعَى dan Isim Alat adalah مَدْعَاةٌ"],"correct":"Isim Makan/Zaman adalah مَدْعًى dan Isim Alat adalah مِدْعًى (Wawu diganti Alif Maqshurah karena jatuh setelah fathah)","explanation":"Bentuk asal Isim Makan/Zaman/Alat: مَدْعَوٌ / مِدْعَوٌ. Karena Wawu berharakat jatuh setelah fathah, Wawu diganti Alif Maqshurah, dan dengan tanwin menjadi مَدْعًى serta مِدْعًى."}}}]},{"id_kalimat":"amogenz_tasrif_004","teks_kalimat":"ضَرَبَ","analysis":[{"id_lafadz":"amogenz_lafadz_004","word":"ضَرَبَ","steps":{"1":{"question":"Apa Wazan dan Bab dari lafadz ضَرَبَ dalam Tasrif Ishtilahi?","options":["Bab 2 (فَعَلَ - يَفْعِلُ)","Bab 1 (فَعَلَ - يَفْعُلُ)","Bab 3 (فَعَلَ - يَفْعَلُ)","Bab 4 (فَعِلَ - يَفْعَلُ)"],"correct":"Bab 2 (فَعَلَ - يَفْعِلُ)","explanation":"Lafadz ضَرَبَ merupakan bentuk Thulathi Mujarrad Bab 2 dengan pola فَعَلَ - يَفْعِلُ (ضَرَبَ - يَضْرِبُ), di mana 'ain fi'il di-fathah-kan pada madhi dan di-kasrah-kan pada mudhori'."},"2":{"question":"Bagaimana susunan lengkap Tasrif Ishtilahi dari lafadz ضَرَبَ?","options":["ضَرَبَ - يَضْرِبُ - ضَرْبًا - فَهُوَ ضَارِبٌ - وَذَاكَ مَضْرُوبٌ - اِضْرِبْ - لَا تَضْرِبْ - مَضْرِبٌ - مَضْرِبٌ - مِضْرَبٌ","ضَرَبَ - يَضْرُبُ - ضَرْبًا - فَهُوَ ضَارِبٌ - وَذَاكَ مَضْرُوبٌ - أُضْرُبْ - لَا تَضْرُبْ - مَضْرَبٌ - مَضْرَبٌ - مِضْرَبٌ","ضَرَبَ - يَضْرَبُ - ضَرْبًا - فَهُوَ ضَارِبٌ - وَذَاكَ مَضْرُوبٌ - اِضْرَبْ - لَا تَضْرَبْ - مَضْرَبٌ - مَضْرَبٌ - مِضْرَبٌ","ضَرَبَ - يَضْرِبُ - ضِرَابًا - فَهُوَ مَضْرُوبٌ - وَذَاكَ ضَارِبٌ - اِضْرِبْ - لَا تَضْرِبْ - مَضْرِبٌ - مَضْرِبٌ - مِضْرَبٌ"],"correct":"ضَرَبَ - يَضْرِبُ - ضَرْبًا - فَهُوَ ضَارِبٌ - وَذَاكَ مَضْرُوبٌ - اِضْرِبْ - لَا تَضْرِبْ - مَضْرِبٌ - مَضْرِبٌ - مِضْرَبٌ","explanation":"Tasrif Ishtilahi lengkap Bab 2: Madhi ضَرَبَ, Mudhori' يَضْرِبُ, Masdar ضَرْبًا, Isim Fa'il ضَارِبٌ, Isim Maf'ul مَضْرُوبٌ, Fi'il Amr اِضْرِبْ, Fi'il Nahi لَا تَضْرِبْ, Isim Zaman/Makan مَضْرِبٌ, dan Isim Alat مِضْرَبٌ."},"3":{"question":"Bagaimana bentuk Tasrif Lughawi Fi'il Madhi dari lafadz ضَرَبَ ketika bertemu dhomir Antum (أَنْتُمْ)?","options":["ضَرَبْتُمْ","ضَرَبُوا","ضَرَبْنَ","ضَرَبْتُنَّ"],"correct":"ضَرَبْتُمْ","explanation":"Untuk dhomir مخاطب جمع مذكر (أَنْتُمْ), Fi'il Madhi ضَرَبَ ditambahi dhomir rafa' mutaharrik Tum (تُمْ) dan lam fi'il (ب) di-sukun-kan, menjadi ضَرَبْتُمْ."},"4":{"question":"Bagaimana bentuk Tasrif Lughawi Fi'il Mudhori' dari lafadz ضَرَبَ ketika bertemu dhomir Humaa Mu'annath (هُمَا مؤنث)?","options":["تَضْرِبَانِ","يَضْرِبَانِ","تَضْرِبُونَ","يَضْرِبْنَ"],"correct":"تَضْرِبَانِ","explanation":"Untuk dhomir غائب تثنية مؤنث (هُمَا مؤنث), Fi'il Mudhori' diawali huruf Ta' mudhoro'ah dan diakhiri Alif Tatsniyah serta Nun Maktuurab (علامة الرفع), menjadi تَضْرِبَانِ."},"5":{"question":"Bagaimana pengaruh Bina' Shahih Salim pada pola tasrifan lafadz ضَرَبَ?","options":["Seluruh huruf asal (ض, ر, ب) tetap utuh tanpa perubahan i'lal, ibdal, maupun idgham pada seluruh susunan tasrifan","Terjadi pembuangan 'ain fi'il saat bersambung dengan dhomir rafa' mutaharrik","Terjadi pemindahan harakat dari 'ain fi'il ke fa' fi'il","Huruf lam fi'il diganti menjadi huruf 'illat pada bentuk mudhori'"],"correct":"Seluruh huruf asal (ض, ر, ب) tetap utuh tanpa perubahan i'lal, ibdal, maupun idgham pada seluruh susunan tasrifan","explanation":"Bina' Shahih Salim adalah fi'il yang huruf asalnya terbebas dari huruf 'illat, hamzah, dan tadh'if, sehingga seluruh konjugasi tasrifannya berjalan sesuai kaidah asal tanpa perubahan huruf."},"6":{"question":"Apa bentuk Fi'il Amr dan Fi'il Nahi dari lafadz ضَرَبَ?","options":["اِضْرِبْ dan لَا تَضْرِبْ","أُضْرُبْ dan لَا تَضْرُبْ","اِضْرَبْ dan لَا تَضْرَبْ","ضَرِّبْ dan لَا تُضَرِّبْ"],"correct":"اِضْرِبْ dan لَا تَضْرِبْ","explanation":"Fi'il Amr dibentuk dengan membuang huruf mudhoro'ah dari تَضْرِبُ dan menambah hamzah washol berharakat kasrah (karena 'ain fi'il kasrah) menjadi اِضْرِبْ. Fi'il Nahi dibentuk dengan menambah Laa Nahiyah menjadi لَا تَضْرِبْ."},"7":{"question":"Apa bentuk Isim Fa'il dan Isim Maf'ul dari lafadz ضَرَبَ?","options":["ضَارِبٌ dan مَضْرُوبٌ","مُضْرِبٌ dan مُضْرَبٌ","ضَرِيبٌ dan مَضْرَبٌ","ضَارِبٌ dan مُضَرَّبٌ"],"correct":"ضَارِبٌ dan مَضْرُوبٌ","explanation":"Isim Fa'il dari Thulathi Mujarrad mengikuti wazan فَاعِلٌ menjadi ضَارِبٌ, sedangkan Isim Maf'ul mengikuti wazan مَفْعُولٌ menjadi مَضْرُوبٌ."},"8":{"question":"Bagaimana bentuk Fi'il Mabni Majhul (pasif) dari lafadz ضَرَبَ dalam Fi'il Madhi dan Fi'il Mudhori'?","options":["ضُرِبَ (Madhi) dan يُضْرَبُ (Mudhori')","ضَرَبَ (Madhi) dan يَضْرِبُ (Mudhori')","ضُرِبَ (Madhi) dan يُضْرِبُ (Mudhori')","ضُرِّبَ (Madhi) dan يُضَرَّبُ (Mudhori')"],"correct":"ضُرِبَ (Madhi) dan يُضْرَبُ (Mudhori')","explanation":"Fi'il Madhi Majhul di-dhommah-kan huruf awal dan di-kasrah-kan sebelum akhir (ضُرِبَ). Fi'il Mudhori' Majhul di-dhommah-kan huruf mudhoro'ah dan di-fathah-kan sebelum akhir (يُضْرَبُ)."}}}]},{"id_kalimat":"amogenz_tasrif_005","teks_kalimat":"مَدَّ","analysis":[{"id_lafadz":"amogenz_lafadz_005","word":"مَدَّ","steps":{"1":{"question":"Apa Wazan asli dan Bab dari lafadz مَدَّ dalam Tasrif Ishtilahi?","options":["Bab 1 (فَعَلَ - يَفْعُلُ) dengan bentuk asal مَدَدَ - يَمْدُدُ","Bab 2 (فَعَلَ - يَفْعِلُ) dengan bentuk asal مَدَدَ - يَمْدِدُ","Bab 4 (فَعِلَ - يَفْعَلُ) dengan bentuk asal مَدِدَ - يَمْدَدُ","Bab 1 (فَعَلَ - يَفْعُلُ) dengan bentuk asal مَدَّ - يَمُدُّ"],"correct":"Bab 1 (فَعَلَ - يَفْعُلُ) dengan bentuk asal مَدَدَ - يَمْدُدُ","explanation":"Lafadz مَدَّ tergolong Bab 1 Thulathi Mujarrad. Bentuk dasarnya sebelum idgham adalah مَدَدَ dengan fi'il mudhori' asal يَمْدُدُ."},"2":{"question":"Bagaimana susunan lengkap Tasrif Ishtilahi dari lafadz مَدَّ?","options":["مَدَّ - يَمُدُّ - مَدًّ - فَهُوَ مَادٌّ - وَذَاكَ مَمْدُودٌ - مُدَّ - لَا تَمُدَّ - مَمَدٌّ - مَمَدٌّ - مِمَدٌّ","مَدَّ - يَمِدُّ - مَدًّ - فَهُوَ مَادٌّ - وَذَاكَ مَمْدُودٌ - مِدَّ - لَا تَمِدَّ - مَمِدٌّ - مَمِدٌّ - مِمَدٌّ","مَدَدَ - يَمْدُدُ - مَدْدًا - فَهُوَ مَادِدٌ - وَذَاكَ مَمْدُودٌ - أُمْدُدْ - لَا تَمْدُدْ - مَمْدَدٌ - مَمْدَدٌ - مِمْدَدٌ","مَدَّ - يَمُدُّ - مُدُودًا - فَهُوَ مَمْدُودٌ - وَذَاكَ مَادٌّ - مُدَّ - لَا تَمُدَّ - مَمَدٌّ - مَمَدٌّ - مِمَدٌّ"],"correct":"مَدَّ - يَمُدُّ - مَدًّ - فَهُوَ مَادٌّ - وَذَاكَ مَمْدُودٌ - مُدَّ - لَا تَمُدَّ - مَمَدٌّ - مَمَدٌّ - مِمَدٌّ","explanation":"Tasrif Ishtilahi ter-idgham dari مَدَّ adalah: Madhi مَدَّ, Mudhori' يَمُدُّ, Masdar مَدًّ, Isim Fa'il مَادٌّ, Isim Maf'ul مَمْدُودٌ, Fi'il Amr مُدَّ, Fi'il Nahi لَا تَمُدَّ, Isim Zaman/Makan مَمَدٌّ, dan Isim Alat مِمَدٌّ."},"3":{"question":"Bagaimana bentuk Tasrif Lughawi Fi'il Madhi dari lafadz مَدَّ ketika bertemu dhomir Hunna (هُنَّ)?","options":["مَدَدْنَ","مَدَّنَ","مَدُّوا","مَدَدْتُنَّ"],"correct":"مَدَدْنَ","explanation":"Ketika bersambung dengan dhomir rafa' mutaharrik seperti Hunna (هُنَّ), idgham wajib dilepas (فك الإدغام) karena lam fi'il di-sukun-kan, sehingga kembali ke bentuk asal menjadi مَدَدْنَ."},"4":{"question":"Bagaimana bentuk Tasrif Lughawi Fi'il Mudhori' dari lafadz مَدَّ ketika bertemu dhomir Antunna (أَنْتُنَّ)?","options":["تَمْدُدْنَ","تَمُدَّنَ","تَمُدُّونَ","تَمْدُدْنَنَّ"],"correct":"تَمْدُدْنَ","explanation":"Pada Fi'il Mudhori' bersambung dengan dhomir Nun Niswah (أَنْتُنَّ), terjadi fakk al-idgham (penguraian dua huruf sejenis) karena lam fi'il sukun, sehingga menjadi تَمْدُدْنَ."},"5":{"question":"Bagaimana pengaruh Bina' Mudho'af pada pola tasrifan lafadz مَدَّ?","options":["Dua huruf sejenis ('ain dan lam fi'il) di-idgham-kan menjadi satu huruf bertasydid jika keduanya berharakat atau huruf kedua berharakat, dan diurai (فك الإدغام) jika bertemu dhomir rafa' mutaharrik","Huruf 'ain fi'il dibuang sepenuhnya di seluruh konjugasi","Huruf lam fi'il diganti menjadi Alif Maqshurah","Tidak ada kaidah idgham maupun fakk al-idgham"],"correct":"Dua huruf sejenis ('ain dan lam fi'il) di-idgham-kan menjadi satu huruf bertasydid jika keduanya berharakat atau huruf kedua berharakat, dan diurai (فك الإدغام) jika bertemu dhomir rafa' mutaharrik","explanation":"Bina' Mudho'af Thulathi ditandai dengan sama-Nya 'ain dan lam fi'il. Hukum utamanya adalah Idgham saat memungkinkan dan Fakk Al-Idgham saat bertemu dhomir rafa' mutaharrik."},"6":{"question":"Apa bentuk Fi'il Amr dan Fi'il Nahi dari lafadz مَدَّ untuk dhomir Anta (أَنْتَ)?","options":["مُدَّ (atau أُمْدُدْ) dan لَا تَمُدَّ (atau لَا تَمْدُدْ)","اِمْدِدْ dan لَا تَمْدِدْ","مَدِّ dan لَا تَمَدَّ","أُمُدَّ dan لَا تُمُدَّ"],"correct":"مُدَّ (atau أُمْدُدْ) dan لَا تَمُدَّ (atau لَا تَمْدُدْ)","explanation":"Fi'il Amr dhomir أَنْتَ pada Bina' Mudho'af boleh di-idgham-kan dengan harakat fathah (مُدَّ) atau diurai tanpa hamzah washol yang dibutuhkan saat idgham lepas (أُمْدُدْ). Demikian pula Fi'il Nahi لَا تَمُدَّ / لَا تَمْدُدْ."},"7":{"question":"Apa bentuk Isim Fa'il dan Isim Maf'ul dari lafadz مَدَّ?","options":["مَادٌّ dan مَمْدُودٌ","مَادِدٌ dan مَمْدُدٌ","مُمِدٌّ dan مُمَدٌّ","مَادٍ dan مَمْدِيٌّ"],"correct":"مَادٌّ dan مَمْدُودٌ","explanation":"Isim Fa'il asal مَادِدٌ di-idgham-kan menjadi مَادٌّ. Isim Maf'ul wazan مَفْعُولٌ adalah مَمْدُودٌ (tanpa idgham karena dipisah oleh Wawu sukun)."},"8":{"question":"Bagaimana bentuk Fi'il Mabni Majhul (pasif) dari lafadz مَدَّ dalam Fi'il Madhi dan Fi'il Mudhori'?","options":["مُدَّ (Madhi) dan يُمَدُّ (Mudhori')","مَدَّ (Madhi) dan يَمُدُّ (Mudhori')","مُدِدَ (Madhi) dan يُمْدَدُ (Mudhori')","مُدَّ (Madhi) dan يُمُدُّ (Mudhori')"],"correct":"مُدَّ (Madhi) dan يُمَدُّ (Mudhori')","explanation":"Madhi Majhul asal مُدِدَ di-idgham-kan menjadi مُدَّ. Mudhori' Majhul asal يُمْدَدُ, harakat fathah Dal pertama dipindah ke Mim lalu di-idgham-kan menjadi يُمَدُّ."},"9":{"question":"Bagaimana ketentuan Idgham pada Isim Zaman, Isim Makan, dan Isim Alat dari lafadz مَدَّ?","options":["Di-idgham-kan menjadi مَمَدٌّ (Isim Zaman/Makan) dan مِمَدٌّ (Isim Alat) karena dua huruf sejenis berharakat sesudah huruf sukun/fathah","Wajib diurai (fakk) menjadi مَمْدَدٌ dan مِمْدَدٌ","Diganti menjadi huruf 'illat Ya' pada akhir kata","Tidak dapat dibentuk Isim Zaman, Makan, maupun Alatnya"],"correct":"Di-idgham-kan menjadi مَمَدٌّ (Isim Zaman/Makan) dan مِمَدٌّ (Isim Alat) karena dua huruf sejenis berharakat sesudah huruf sukun/fathah","explanation":"Bentuk asal Isim Zaman/Makan adalah مَمْدَدٌ (wazan مَفْعَلٌ) dan Isim Alat مِمْدَدٌ (wazan مِفْعَلٌ). Harakat 'ain fi'il dipindah ke fa' fi'il yang sukun lalu kedua Dal di-idgham-kan menjadi مَمَدٌّ dan مِمَدٌّ."}}}]},{"id_kalimat":"amogenz_tasrif_006","teks_kalimat":"بَاعَ","analysis":[{"id_lafadz":"amogenz_lafadz_006","word":"بَاعَ","steps":{"1":{"question":"Apa Wazan asli dan Bab dari lafadz بَاعَ dalam Tasrif Ishtilahi?","options":["Bab 2 (فَعَلَ - يَفْعِلُ) dengan bentuk asal بَيَعَ - يَبْيِعُ","Bab 1 (فَعَلَ - يَفْعُلُ) dengan bentuk asal بَوَعَ - يَبْوُعُ","Bab 3 (فَعَلَ - يَفْعَلُ) dengan bentuk asal بَيَعَ - يَبْيَعُ","Bab 4 (فَعِلَ - يَفْعَلُ) dengan bentuk asal بَيِعَ - يَبْيَعُ"],"correct":"Bab 2 (فَعَلَ - يَفْعِلُ) dengan bentuk asal بَيَعَ - يَبْيِعُ","explanation":"Lafadz بَاعَ merupakan Thulathi Mujarrad Bab 2 dengan bentuk asal بَيَعَ (Madhi) dan يَبْيِعُ (Mudhori')."},"2":{"question":"Bagaimana susunan lengkap Tasrif Ishtilahi dari lafadz بَاعَ?","options":["بَاعَ - يَبِيعُ - بَيْعًا - فَهُوَ بَائِعٌ - وَذَاكَ مَبِيعٌ - بِعْ - لَا تَبِعْ - مَبَاعٌ - مَبَاعٌ - مِبْيَعٌ","بَاعَ - يَبُوعُ - بَوْعًا - فَهُوَ بَائِعٌ - وَذَاكَ مَبُوعٌ - بُعْ - لَا تَبُعْ - مَبَاعٌ - مَبَاعٌ - مِبْوَاعٌ","بَاعَ - يَبِيعُ - بَيْعَةً - فَهُوَ مَبِيعٌ - وَذَاكَ بَائِعٌ - اِبْيِعْ - لَا تَبْيِعْ - مَبْيَعٌ - مَبْيَعٌ - مِبْيَعٌ","بَيَعَ - يَبْيِعُ - بَيْعًا - فَهُوَ بَايِعٌ - وَذَاكَ مَبْيُوعٌ - اِبْيِعْ - لَا تَبْيِعْ - مَبْيَعٌ - مَبْيَعٌ - مِبْيَعٌ"],"correct":"بَاعَ - يَبِيعُ - بَيْعًا - فَهُوَ بَائِعٌ - وَذَاكَ مَبِيعٌ - بِعْ - لَا تَبِعْ - مَبَاعٌ - مَبَاعٌ - مِبْيَعٌ","explanation":"Deretan Tasrif Ishtilahi ter-i'lal dari بَاعَ: Madhi بَاعَ, Mudhori' يَبِيعُ, Masdar بَيْعًا, Isim Fa'il بَائِعٌ, Isim Maf'ul مَبِيعٌ, Fi'il Amr بِعْ, Fi'il Nahi لَا تَبِعْ, Isim Zaman/Makan مَبَاعٌ, Isim Alat مِبْيَعٌ."},"3":{"question":"Bagaimana bentuk Tasrif Lughawi Fi'il Madhi dari lafadz بَاعَ ketika bertemu dhomir Anta (أَنْتَ)?","options":["بِعْتَ","بَاعْتَ","بُعْتَ","بَيَعْتَ"],"correct":"بِعْتَ","explanation":"Saat bersambung dhomir rafa' mutaharrik (أَنْتَ), lam fi'il di-sukun-kan (بَاعْتَ). Terjadi iltiqa' sakinain (Alif sukun & Ain sukun), Alif dibuang. Fa' fi'il (ب) di-kasrah-kan (بِعْتَ) sebagai penanda bahwa huruf 'illat yang terbuang adalah Ya'."},"4":{"question":"Bagaimana bentuk Tasrif Lughawi Fi'il Mudhori' dari lafadz بَاعَ ketika bertemu dhomir Antum (أَنْتُمْ)?","options":["تَبِيعُونَ","تَبَاعُونَ","تَبْيِعُونَ","تَبِيعُنَّ"],"correct":"تَبِيعُونَ","explanation":"Untuk dhomir أَنْتُمْ, Fi'il Mudhori' يَبِيعُ diawali Ta' mudhoro'ah dan diakhiri Wawu Jama' serta Nun Tsubut, menjadi تَبِيعُونَ."},"5":{"question":"Bagaimana pengaruh Bina' Ajwaf Ya'i pada pola tasrifan lafadz بَاعَ?","options":["Huruf 'illat Ya' pada بَيَعَ berharakat sesudah fathah diganti Alif (بَاعَ); sedangkan pada mudhori' يَبْيِعُ harakat kasrah Ya' dipindah ke huruf shahih sebelumnya (Ba')","Huruf Ya' dibuang di seluruh konjugasi tanpa sisa","Huruf Ya' diganti Wawu pada bentuk Mudhori'","Tidak mengalami proses I'lal sama sekali"],"correct":"Huruf 'illat Ya' pada بَيَعَ berharakat sesudah fathah diganti Alif (بَاعَ); sedangkan pada mudhori' يَبْيِعُ harakat kasrah Ya' dipindah ke huruf shahih sebelumnya (Ba')","explanation":"Pada Madhi بَيَعَ, Ya' hidup jatuh setelah fathah diganti Alif menjadi بَاعَ. Pada Mudhori' يَبْيِعُ, kasrah pada Ya' dipindah ke Ba' yang sukun menjadi يَبِيعُ."},"6":{"question":"Apa bentuk Fi'il Amr dan Fi'il Nahi dari lafadz بَاعَ untuk dhomir Anta (أَنْتَ)?","options":["بِعْ dan لَا تَبِعْ","اِبْيِعْ dan لَا تَبْيِعْ","بَاعْ dan لَا تَبَاعْ","بُعْ dan لَا تَبُعْ"],"correct":"بِعْ dan لَا تَبِعْ","explanation":"Dari mudhori' majzum تَبِيعْ, huruf mudhoro'ah dibuang. Terjadi iltiqa' sakinain antara Ya' sukun dan Ain sukun, maka Ya' dibuang sehingga menjadi بِعْ. Nahinya لَا تَبِعْ."},"7":{"question":"Apa bentuk Isim Fa'il dan Isim Maf'ul dari lafadz بَاعَ?","options":["بَائِعٌ dan مَبِيعٌ","بَايِعٌ dan مَبْيُوعٌ","مَبِيعٌ dan بَائِعٌ","بَائِعٌ dan مَبُوعٌ"],"correct":"بَائِعٌ dan مَبِيعٌ","explanation":"Isim Fa'il asal بَايِعٌ -> Ya' diganti Hamzah karena jatuh sesudah Alif Zaidah (بَائِعٌ). Isim Maf'ul asal مَبْيُوعٌ -> harakat dhommah Ya' dipindah ke Ba', lalu Ya' diganti kasrah/tetap dan Wawu dibuang karena iltiqa' sakinain menjadi مَبِيعٌ."},"8":{"question":"Bagaimana bentuk Fi'il Mabni Majhul (pasif) dari lafadz بَاعَ dalam Fi'il Madhi dan Fi'il Mudhori'?","options":["بِيعَ (Madhi) dan يُبَاعُ (Mudhori')","بُيِعَ (Madhi) dan يُبْيَعُ (Mudhori')","بُوعَ (Madhi) dan يُبِيعُ (Mudhori')","بِيعَ (Madhi) dan يُبِيعُ (Mudhori')"],"correct":"بِيعَ (Madhi) dan يُبَاعُ (Mudhori')","explanation":"Madhi Majhul asal بُيِعَ -> kasrah Ya' dipindah ke Ba' dan dhommah Ba' dibuang menjadi بِيعَ. Mudhori' Majhul asal يُبْيَعُ -> fathah Ya' dipindah ke Ba' dan Ya' diganti Alif menjadi يُبَاعُ."},"9":{"question":"Bagaimana penyesuaian bentuk Isim Makan dan Isim Zaman dari lafadz بَاعَ menurut kaidah I'lal?","options":["Bentuknya adalah مَبَاعٌ, berasal dari مَبْيَعٌ yang harakat fathah Ya'-nya dipindah ke Ba' lalu Ya' diganti Alif","Bentuknya adalah مَبِيعٌ tanpa ada perubahan huruf","Bentuknya adalah مَبْيَعٌ tanpa transfer harakat","Bentuknya adalah مِبْيَاعٌ"],"correct":"Bentuknya adalah مَبَاعٌ, berasal dari مَبْيَعٌ yang harakat fathah Ya'-nya dipindah ke Ba' lalu Ya' diganti Alif","explanation":"Isim Makan/Zaman Ajwaf mengikuti wazan مَفْعَلٌ (مَبْيَعٌ). Harakat fathah pada Ya' dipindah ke Ba' yang sukun, lalu Ya' diganti Alif karena berharakat setelah fathah, menghasilkan مَبَاعٌ."}}}]},{"id_kalimat":"amogenz_tasrif_007","teks_kalimat":"وَعَدَ","analysis":[{"id_lafadz":"amogenz_lafadz_007","word":"وَعَدَ","steps":{"1":{"question":"Apa Wazan dan Bab dari lafadz وَعَدَ dalam Tasrif Ishtilahi?","options":["Bab 2 (فَعَلَ - يَفْعِلُ) dengan wazan asal وَعَدَ - يَوْعِدُ","Bab 1 (فَعَلَ - يَفْعُلُ) dengan wazan asal وَعَدَ - يَوْعُدُ","Bab 3 (فَعَلَ - يَفْعَلُ) dengan wazan asal وَعَدَ - يَوْعَدُ","Bab 4 (فَعِلَ - يَفْعَلُ) dengan wazan asal وَعِدَ - يَوْعَدُ"],"correct":"Bab 2 (فَعَلَ - يَفْعِلُ) dengan wazan asal وَعَدَ - يَوْعِدُ","explanation":"Lafadz وَعَدَ tergolong Bab 2 Thulathi Mujarrad (فَعَلَ - يَفْعِلُ). Bentuk dasarnya sebelum dibuang huruf 'illat-nya adalah وَعَدَ - يَوْعِدُ."},"2":{"question":"Bagaimana susunan lengkap Tasrif Ishtilahi dari lafadz وَعَدَ?","options":["وَعَدَ - يَعِدُ - وَعْدًا - فَهُوَ وَاعِدٌ - وَذَاكَ مَوْعُودٌ - عِدْ - لَا تَعِدْ - مَوْعِدٌ - مَوْعِدٌ - مِيعَادٌ","وَعَدَ - يَوْعِدُ - وَعْدًا - فَهُوَ وَاعِدٌ - وَذَاكَ مَوْعُودٌ - اِوْعِدْ - لَا تَوْعِدْ - مَوْعَدٌ - مَوْعَدٌ - مِيعَادٌ","وَعَدَ - يَعُدُ - وَعْدًا - فَهُوَ وَاعِدٌ - وَذَاكَ مَوْعُودٌ - عُدْ - لَا تَعُدْ - مَوْعِدٌ - مَوْعِدٌ - مِيعَادٌ","وَعَدَ - يَعِدُ - وَعِيدًا - فَهُوَ مَوْعُودٌ - وَذَاكَ وَاعِدٌ - عِدْ - لَا تَعِدْ - مَوْعَدٌ - مَوْعَدٌ - مِيعَادٌ"],"correct":"وَعَدَ - يَعِدُ - وَعْدًا - فَهُوَ وَاعِدٌ - وَذَاكَ مَوْعُودٌ - عِدْ - لَا تَعِدْ - مَوْعِدٌ - مَوْعِدٌ - مِيعَادٌ","explanation":"Susunan Ishtilahi utuh untuk وَعَدَ: Madhi وَعَدَ, Mudhori' يَعِدُ, Masdar وَعْدًا, Isim Fa'il وَاعِدٌ, Isim Maf'ul مَوْعُودٌ, Amr عِدْ, Nahi لَا تَعِدْ, Zaman/Makan مَوْعِدٌ, Isim Alat مِيعَادٌ."},"3":{"question":"Bagaimana bentuk Tasrif Lughawi Fi'il Madhi dari lafadz وَعَدَ ketika bertemu dhomir Antum (أَنْتُمْ)?","options":["وَعَدْتُمْ","وَعَدُوا","وَعَدْنَ","وَعَدْتُنَّ"],"correct":"وَعَدْتُمْ","explanation":"Untuk dhomir مخاطب جمع مذكر (أَنْتُمْ), Fi'il Madhi وَعَدَ di-sukun-kan lam fi'il-nya (د) dan ditambahi dhomir rafa' mutaharrik Tum (تُمْ), menjadi وَعَدْتُمْ."},"4":{"question":"Bagaimana bentuk Tasrif Lughawi Fi'il Mudhori' dari lafadz وَعَدَ ketika bertemu dhomir Hum (هُمْ)?","options":["يَعِدُونَ","يَوْعِدُونَ","تَعِدُونَ","يَعِدْنَ"],"correct":"يَعِدُونَ","explanation":"Fi'il Mudhori' dari وَعَدَ adalah يَعِدُ (setelah Wawu dibuang). Ketika bersambung dhomir هُمْ, ditambah Wawu Jama' dan Nun Tsubut menjadi يَعِدُونَ."},"5":{"question":"Bagaimana pengaruh Bina' Mithal Wawi pada pola tasrifan lafadz وَعَدَ?","options":["Huruf Wawu pada fa' fi'il dibuang pada Fi'il Mudhori' (يَعِدُ) karena jatuh di antara harakat fathah (huruf mudhoro'ah) dan kasrah ('ain fi'il)","Huruf Wawu diganti Alif pada bentuk Fi'il Madhi","Huruf Wawu dibuang pada seluruh bentuk tasrifan tanpa terkecuali","Huruf Wawu di-idgham-kan ke huruf berikutnya"],"correct":"Huruf Wawu pada fa' fi'il dibuang pada Fi'il Mudhori' (يَعِدُ) karena jatuh di antara harakat fathah (huruf mudhoro'ah) dan kasrah ('ain fi'il)","explanation":"Bina' Mithal Wawi Bab 2 mengalami pembuangan Wawu pada Mudhori' (يَوْعِدُ -> يَعِدُ) karena Wawu berada di antara fathah dan kasrah lazimah."},"6":{"question":"Apa bentuk Fi'il Amr dan Fi'il Nahi dari lafadz وَعَدَ?","options":["عِدْ dan لَا تَعِدْ","اِوْعِدْ dan لَا تَوْعِدْ","عُدْ dan لَا تَعُدْ","أَوْعِدْ dan لَا تُوعِدْ"],"correct":"عِدْ dan لَا تَعِدْ","explanation":"Fi'il Amr dibuat dari mudhori' تَعِدُ. Dibuang huruf mudhoro'ah (تَـ), tersisa عِدْ (karena huruf pertamanya sudah berharakat kasrah, tidak memerlukan hamzah washol). Nahinya لَا تَعِدْ."},"7":{"question":"Apa bentuk Isim Fa'il dan Isim Maf'ul dari lafadz وَعَدَ?","options":["وَاعِدٌ dan مَوْعُودٌ","مُوعِدٌ dan مُوعَدٌ","وَعِيدٌ dan مَوْعَدٌ","وَاعٍ dan مَوْعِيٌّ"],"correct":"وَاعِدٌ dan مَوْعُودٌ","explanation":"Isim Fa'il mengikuti wazan فَاعِلٌ menjadi وَاعِدٌ (Wawu tidak dibuang karena berada di awal). Isim Maf'ul mengikuti wazan مَفْعُولٌ menjadi مَوْعُودٌ."},"8":{"question":"Bagaimana bentuk Fi'il Mabni Majhul (pasif) dari lafadz وَعَدَ dalam Fi'il Madhi dan Fi'il Mudhori'?","options":["وُعِدَ (Madhi) dan يُوعَدُ (Mudhori')","وُعِدَ (Madhi) dan يُعَدُ (Mudhori')","وَعِدَ (Madhi) dan يُوعِدُ (Mudhori')","وُعِّدَ (Madhi) dan يُوَعَّدُ (Mudhori')"],"correct":"وُعِدَ (Madhi) dan يُوعَدُ (Mudhori')","explanation":"Madhi Majhul: وُعِدَ. Pada Mudhori' Majhul يُوعَدُ, huruf Wawu dikembalikan lagi (tidak dibuang) karena huruf sebelum Wawu berharakat dhommah dan huruf setelah Wawu berharakat fathah (bukan kasrah)."},"9":{"question":"Bagaimana bentuk Isim Zaman, Isim Makan, dan Isim Alat dari lafadz وَعَدَ beserta alasannya?","options":["Isim Zaman/Makan ber-wazan مَفْعِلٌ (مَوْعِدٌ) karena Bina' Mithal Wawi, dan Isim Alat ber-wazan مِفْعَالٌ (مِيعَادٌ) di mana Wawu diganti Ya' karena sukun setelah kasrah","Isim Zaman/Makan adalah مَوْعَدٌ dan Isim Alat adalah مِوْعَادٌ","Isim Zaman/Makan adalah مَعِدٌ dan Isim Alat adalah مِعَادٌ","Isim Zaman/Makan adalah مَوْعُودٌ dan Isim Alat adalah مِيعَدٌ"],"correct":"Isim Zaman/Makan ber-wazan مَفْعِلٌ (مَوْعِدٌ) karena Bina' Mithal Wawi, dan Isim Alat ber-wazan مِفْعَالٌ (مِيعَادٌ) di mana Wawu diganti Ya' karena sukun setelah kasrah","explanation":"Pengecualian khusus Mithal Wawi: Isim Zaman/Makan mengikuti wazan مَفْعِلٌ (مَوْعِدٌ). Pada Isim Alat مِفْعَالٌ (مِوْعَادٌ), Wawu sukun jatuh setelah kasrah diganti Ya' menjadi مِيعَادٌ."}}}]},{"id_kalimat":"amogenz_tasrif_008","teks_kalimat":"رَمَى","analysis":[{"id_lafadz":"amogenz_lafadz_008","word":"رَمَى","steps":{"1":{"question":"Apa Wazan asli dan Bab dari lafadz رَمَى dalam Tasrif Ishtilahi?","options":["Bab 2 (فَعَلَ - يَفْعِلُ) dengan wazan asal رَمَيَ - يَرْمِيُ","Bab 3 (فَعَلَ - يَفْعَلُ) dengan wazan asal رَمَيَ - يَرْمَيُ","Bab 1 (فَعَلَ - يَفْعُلُ) dengan wazan asal رَمَوَ - يَرْمُوُ","Bab 4 (فَعِلَ - يَفْعَلُ) dengan wazan asal رَمِيَ - يَرْمَيُ"],"correct":"Bab 2 (فَعَلَ - يَفْعِلُ) dengan wazan asal رَمَيَ - يَرْمِيُ","explanation":"Lafadz رَمَى tergolong Bab 2 Thulathi Mujarrad dengan bentuk dasar رَمَيَ - يَرْمِيُ sebelum di-i'lal."},"2":{"question":"Bagaimana susunan lengkap Tasrif Ishtilahi dari lafadz رَمَى?","options":["رَمَى - يَرْمِي - رَمْيًا - فَهُوَ رَامٍ - وَذَاكَ مَرْمِيٌّ - اِرْمِ - لَا تَرْمِ - مَرْمًى - مَرْمًى - مِرْمًى","رَمَى - يَرْمَى - رَمْيًا - فَهُوَ رَامٍ - وَذَاكَ مَرْمًى - اِرْمَ - لَا تَرْمَ - مَرْمًى - مَرْمًى - مِرْمًى","رَمَى - يَرْمِي - رِمَايَةً - فَهُوَ مَرْمِيٌّ - وَذَاكَ رَامٍ - اِرْمِ - لَا تَرْمِ - مَرْمِيٌّ - مَرْمِيٌّ - مِرْمًى","رَمَيَ - يَرْمِيُ - رَمْيًا - فَهُوَ رَامِيٌ - وَذَاكَ مَرْمُويٌ - اِرْمِيْ - لَا تَرْمِيْ - مَرْمَيٌ - مَرْمَيٌ - مِرْمَيٌ"],"correct":"رَمَى - يَرْمِي - رَمْيًا - فَهُوَ رَامٍ - وَذَاكَ مَرْمِيٌّ - اِرْمِ - لَا تَرْمِ - مَرْمًى - مَرْمًى - مِرْمًى","explanation":"Tasrif Ishtilahi utuh ter-i'lal dari رَمَى: Madhi رَمَى, Mudhori' يَرْمِي, Masdar رَمْيًا, Isim Fa'il رَامٍ, Isim Maf'ul مَرْمِيٌّ, Amr اِرْمِ, Nahi لَا تَرْمِ, Zaman/Makan مَرْمًى, Isim Alat مِرْمًى."},"3":{"question":"Bagaimana bentuk Tasrif Lughawi Fi'il Madhi dari lafadz رَمَى ketika bertemu dhomir Hum (هُمْ)?","options":["رَمَوْا","رَمَيُوا","رَمُوا","رَمَيْنَا"],"correct":"رَمَوْا","explanation":"Bentuk asal رَمَيُوا (dhomir هُمْ) mengalami pembuangan Ya' lam fi'il karena iltiqa' sakinain dengan Wawu Jama', dan Mim tetap fathah untuk menunjukkan huruf terbuang adalah Ya', menjadi رَمَوْا."},"4":{"question":"Bagaimana bentuk Tasrif Lughawi Fi'il Mudhori' dari lafadz رَمَى ketika bertemu dhomir Antum (أَنْتُمْ)?","options":["تَرْمُونَ","تَرْمِيُونَ","تَرْمَيُونَ","تَرْمِينَ"],"correct":"تَرْمُونَ","explanation":"Pada dhomir أَنْتُمْ, bentuk asal تَرْمِيُونَ mengalami pembungan dhommah Ya' karena itsqal lalu Ya' dibuang karena iltiqa' sakinain dengan Wawu Jama', Mim di-dhommah-kan agar sesuai Wawu, menjadi تَرْمُونَ."},"5":{"question":"Bagaimana pengaruh Bina' Naqish Ya'i pada pola tasrifan lafadz رَمَى?","options":["Huruf 'illat Ya' pada رَمَيَ diganti Alif (رَمَى) karena berharakat setelah Fathah, dan dhommah-nya ditiadakan pada Mudhori' (يَرْمِي) karena itsqal","Huruf Ya' diganti Wawu pada seluruh bentuk tasrifan","Huruf Ya' dibuang tanpa sisa pada Fi'il Madhi","Tidak mengalami proses I'lal"],"correct":"Huruf 'illat Ya' pada رَمَيَ diganti Alif (رَمَى) karena berharakat setelah Fathah, dan dhommah-nya ditiadakan pada Mudhori' (يَرْمِي) karena itsqal","explanation":"Pada Madhi رَمَيَ, Ya' berharakat sesudah fathah diganti Alif Maqshurah menjadi رَمَى. Pada Mudhori' يَرْمِيُ, dhommah di atas Ya' digugurkan karena berat diucapkan (itsqal)."},"6":{"question":"Apa bentuk Fi'il Amr dan Fi'il Nahi dari lafadz رَمَى?","options":["اِرْمِ dan لَا تَرْمِ","أُرْمُ dan لَا تَرْمُ","اِرْمَى dan لَا تَرْمَى","رِمْ dan لَا تَرِمْ"],"correct":"اِرْمِ dan لَا تَرْمِ","explanation":"Tanda jazam Fi'il Amr dan Nahi pada Bina' Naqish adalah membuang lam fi'il (huruf 'illat Ya'). Maka dari يَرْمِي menjadi اِرْمِ (dengan hamzah washol kasrah) dan لَا تَرْمِ."},"7":{"question":"Apa bentuk Isim Fa'il dan Isim Maf'ul dari lafadz رَمَى?","options":["رَامٍ dan مَرْمِيٌّ","رَامِيٌ dan مَرْمُويٌ","رَامٍ dan مَرْمُوٌّ","مُرْمٍ dan مُرْمًى"],"correct":"رَامٍ dan مَرْمِيٌّ","explanation":"Isim Fa'il asal رَامِيٌ -> Ya' dibuang pada keadaan rafa'/jar menjadi رَامٍ. Isim Maf'ul asal مَرْمُويٌ -> Wawu diganti Ya' karena berkumpul Wawu & Ya' di mana yang pertama sukun, lalu di-idgham-kan menjadi مَرْمِيٌّ."},"8":{"question":"Bagaimana bentuk Fi'il Mabni Majhul (pasif) dari lafadz رَمَى dalam Fi'il Madhi dan Fi'il Mudhori'?","options":["رُمِيَ (Madhi) dan يُرْمَى (Mudhori')","رُمِيَ (Madhi) dan يُرْمِي (Mudhori')","رُمَى (Madhi) dan يُرْمَى (Mudhori')","رُمِّيَ (Madhi) dan يُرَمَّى (Mudhori')"],"correct":"رُمِيَ (Madhi) dan يُرْمَى (Mudhori')","explanation":"Madhi Majhul di-dhommah awal dan di-kasrah sebelum akhir: رُمِيَ (Ya' tampak fathah). Mudhori' Majhul يُرْمَيُ -> Ya' berharakat sesudah fathah diganti Alif Maqshurah menjadi يُرْمَى."},"9":{"question":"Bagaimana pembentukan Isim Maf'ul, Isim Zaman, dan Isim Makan dari lafadz رَمَى menurut kaidah I'lal?","options":["Isim Maf'ul asal مَرْمُويٌ di-idgham-kan menjadi مَرْمِيٌّ, sedangkan Isim Zaman/Makan ber-wazan مَفْعَلٌ (مَرْمَيٌ -> مَرْمًى) dengan mengganti Ya' menjadi Alif","Isim Maf'ul adalah مَرْمُوٌّ dan Isim Zaman adalah مَرْمِيٌّ","Isim Maf'ul adalah مَرْمًى dan Isim Zaman adalah مَرْمِيٌّ","Seluruhnya dibentuk tanpa proses I'lal"],"correct":"Isim Maf'ul asal مَرْمُويٌ di-idgham-kan menjadi مَرْمِيٌّ, sedangkan Isim Zaman/Makan ber-wazan مَفْعَلٌ (مَرْمَيٌ -> مَرْمًى) dengan mengganti Ya' menjadi Alif","explanation":"Pada Isim Maf'ul, Wawu wazan bertemu Ya' lam fi'il sehingga Wawu diubah jadi Ya' lalu di-idgham-kan (مَرْمِيٌّ). Pada Isim Zaman/Makan (مَرْمَيٌ), Ya' diganti Alif Maqshurah bertanwin menjadi مَرْمًى."}}}]},{"id_kalimat":"amogenz_tasrif_009","teks_kalimat":"أَكَلَ","analysis":[{"id_lafadz":"amogenz_lafadz_009","word":"أَكَلَ","steps":{"1":{"question":"Apa Wazan dan Bab dari lafadz أَكَلَ dalam Tasrif Ishtilahi?","options":["Bab 1 (فَعَلَ - يَفْعُلُ)","Bab 2 (فَعَلَ - يَفْعِلُ)","Bab 3 (فَعَلَ - يَفْعَلُ)","Bab 4 (فَعِلَ - يَفْعَلُ)"],"correct":"Bab 1 (فَعَلَ - يَفْعُلُ)","explanation":"Lafadz أَكَلَ tergolong Bab 1 Thulathi Mujarrad (فَعَلَ - يَفْعُلُ), di mana 'ain fi'il-nya di-dhommah-kan pada fi'il mudhori' (أَكَلَ - يَأْكُلُ)."},"2":{"question":"Bagaimana susunan lengkap Tasrif Ishtilahi dari lafadz أَكَلَ?","options":["أَكَلَ - يَأْكُلُ - أَكْلًا - فَهُوَ آكِلٌ - وَذَاكَ مَأْكُولٌ - كُلْ - لَا تَأْكُلْ - مَأْكَلٌ - مَأْكَلٌ - مِئْكَلٌ","أَكَلَ - يَأْكِلُ - أَكْلًا - فَهُوَ آكِلٌ - وَذَاكَ مَأْكُولٌ - اِئْكِلْ - لَا تَأْكِلْ - مَأْكِلٌ - مَأْكِلٌ - مِئْكَلٌ","أَكَلَ - يَأْكُلُ - أُكُلًا - فَهُوَ مَأْكُولٌ - وَذَاكَ آكِلٌ - أُؤْكُلْ - لَا تَأْكُلْ - مَأْكَلٌ - مَأْكَلٌ - مِئْكَلٌ","أَكَلَ - يَأْكَلُ - أَكْلًا - فَهُوَ آكِلٌ - وَذَاكَ مَأْكُولٌ - اِئْكَلْ - لَا تَأْكَلْ - مَأْكَلٌ - مَأْكَلٌ - مِئْكَلٌ"],"correct":"أَكَلَ - يَأْكُلُ - أَكْلًا - فَهُوَ آكِلٌ - وَذَاكَ مَأْكُولٌ - كُلْ - لَا تَأْكُلْ - مَأْكَلٌ - مَأْكَلٌ - مِئْكَلٌ","explanation":"Tasrif Ishtilahi utuh dari أَكَلَ: Madhi أَكَلَ, Mudhori' يَأْكُلُ, Masdar أَكْلًا, Isim Fa'il آكِلٌ, Isim Maf'ul مَأْكُولٌ, Amr كُلْ, Nahi لَا تَأْكُلْ, Zaman/Makan مَأْكَلٌ, Isim Alat مِئْكَلٌ."},"3":{"question":"Bagaimana bentuk Tasrif Lughawi Fi'il Madhi dari lafadz أَكَلَ ketika bertemu dhomir Ana (أَنَا)?","options":["أَكَلْتُ","آكَلْتُ","أَكَلْنَا","أَكَلُوا"],"correct":"أَكَلْتُ","explanation":"Untuk dhomir المتكلم وحده (أَنَا), Fi'il Madhi أَكَلَ di-sukun-kan lam fi'il-nya (ل) dan ditambahi dhomir Tu (تُ), menjadi أَكَلْتُ."},"4":{"question":"Bagaimana bentuk Tasrif Lughawi Fi'il Mudhori' dari lafadz أَكَلَ ketika bertemu dhomir Ana (أَنَا)?","options":["آكُلُ","أَأْكُلُ","نَأْكُلُ","يَأْكُلُ"],"correct":"آكُلُ","explanation":"Bentuk asal dhomir أَنَا pada fi'il mudhori' adalah أَأْكُلُ (berkumpul dua hamzah). Sesuai kaidah I'lal, hamzah kedua yang sukun diganti Alif Mad menjadi آكُلُ."},"5":{"question":"Bagaimana pengaruh Bina' Mahmuz Fa pada pola tasrifan lafadz أَكَلَ?","options":["Fa' fi'il berupa Hamzah. Jika dua hamzah berkumpul di awal kata dengan yang pertama berharakat dan kedua sukun, hamzah kedua diganti huruf Mad yang sesuai harakat hamzah pertama","Hamzah dibuang di seluruh bentuk tasrifan tanpa sisa","Hamzah diganti menjadi huruf 'illat Wawu di seluruh bentuk","Bina' Mahmuz Fa di-idgham-kan ke huruf sesudahnya"],"correct":"Fa' fi'il berupa Hamzah. Jika dua hamzah berkumpul di awal kata dengan yang pertama berharakat dan kedua sukun, hamzah kedua diganti huruf Mad yang sesuai harakat hamzah pertama","explanation":"Lafadz أَكَلَ merupakan Bina' Mahmuz Fa. Kaidah utamanya: saat dua hamzah berkumpul (seperti pada Fi'il Mudhori' dhomir Ana: أَأْكُلُ), hamzah kedua diubah menjadi Alif Mad (آكُلُ)."},"6":{"question":"Apa bentuk Fi'il Amr dan Fi'il Nahi dari lafadz أَكَلَ?","options":["كُلْ dan لَا تَأْكُلْ","أُؤْكُلْ dan لَا تَأْكُلْ","اِئْكُلْ dan لَا تَأْكِلْ","آكُلْ dan لَا تُؤْكُلْ"],"correct":"كُلْ dan لَا تَأْكُلْ","explanation":"Khusus pada Fi'il Amr lafadz أَكَلَ, Hamzah fa' fi'il dibuang secara khusus untuk mempermudah/meringankan pengucapan (تخفيفًا لكثرة الاستعمال) menjadi كُلْ. Nahinya tetap لَا تَأْكُلْ."},"7":{"question":"Apa bentuk Isim Fa'il dan Isim Maf'ul dari lafadz أَكَلَ?","options":["آكِلٌ dan مَأْكُولٌ","أَاكِلٌ dan مَأْكُولٌ","مُؤْكِلٌ dan مُؤْكَلٌ","آكِلٌ dan مَأْكِيلٌ"],"correct":"آكِلٌ dan مَأْكُولٌ","explanation":"Isim Fa'il asal أَاكِلٌ -> Hamzah fa' fi'il bertemu Alif wazan فَاعِلٌ ditulis dengan Alif Mad (آكِلٌ). Isim Maf'ul mengikuti wazan مَفْعُولٌ menjadi مَأْكُولٌ."},"8":{"question":"Bagaimana bentuk Fi'il Mabni Majhul (pasif) dari lafadz أَكَلَ dalam Fi'il Madhi dan Fi'il Mudhori'?","options":["أُكِلَ (Madhi) dan يُؤْكَلُ (Mudhori')","أُكِلَ (Madhi) dan يُأْكَلُ (Mudhori')","آكِلَ (Madhi) dan يُؤْكُلُ (Mudhori')","أُكِّلَ (Madhi) dan يُؤَكَّلُ (Mudhori')"],"correct":"أُكِلَ (Madhi) dan يُؤْكَلُ (Mudhori')","explanation":"Madhi Majhul: أُكِلَ (di-dhommah awal, di-kasrah sebelum akhir). Mudhori' Majhul: يُؤْكَلُ (di-dhommah huruf mudhoro'ah, Hamzah ditulis di atas Wawu karena sukun sesudah dhommah, dan 'ain fi'il di-fathah-kan)."},"9":{"question":"Mengapa terjadi pembuangan Hamzah fa' fi'il pada Fi me-Amr lafadz أَكَلَ?","options":["Dibuang untuk takhfif (meringankan pengucapan) karena sangat sering digunakan dalam percakapan (لكثرة الاستعمال), sehingga menjadi كُلْ tanpa memerlukan Hamzah Washol","Dibuang karena mengikuti kaidah penimbangan iltiqa' sakinain","Dibuang karena diganti oleh huruf 'illat Ya'","Dibuang karena mengikuti wazan Bab 4"],"correct":"Dibuang untuk takhfif (meringankan pengucapan) karena sangat sering digunakan dalam percakapan (لكثرة الاستعمال), sehingga menjadi كُلْ tanpa memerlukan Hamzah Washol","explanation":"Sebagaimana dijelaskan para ulama Shorof, beberapa fi'il mahmuz fa seperti أَكَلَ (كُلْ), أَخَذَ (خُذْ), dan أَمَرَ (مُرْ) membuang fa' fi'il-nya pada Fi'il Amr demi takhfif akibat frekuensi pemakaian yang sangat tinggi."}}}]},{"id_kalimat":"amogenz_tasrif_010","teks_kalimat":"عَلِمَ","analysis":[{"id_lafadz":"amogenz_lafadz_010","word":"عَلِمَ","steps":{"1":{"question":"Apa Wazan dan Bab dari lafadz عَلِمَ dalam Tasrif Ishtilahi?","options":["Bab 4 (فَعِلَ - يَفْعَلُ)","Bab 1 (فَعَلَ - يَفْعُلُ)","Bab 2 (فَعَلَ - يَفْعِلُ)","Bab 6 (فَعِلَ - يَفْعِلُ)"],"correct":"Bab 4 (فَعِلَ - يَفْعَلُ)","explanation":"Lafadz عَلِمَ merupakan Thulathi Mujarrad Bab 4 dengan wazan فَعِلَ - يَفْعَلُ (عَلِمَ - يَعْلَمُ), di mana 'ain fi'il di-kasrah-kan pada fi'il madhi dan di-fathah-kan pada fi'il mudhori'."},"2":{"question":"Bagaimana susunan lengkap Tasrif Ishtilahi dari lafadz عَلِمَ?","options":["عَلِمَ - يَعْلَمُ - عِلْمًا - فَهُوَ عَالِمٌ - وَذَاكَ مَعْلُومٌ - اِعْلَمْ - لَا تَعْلَمْ - مَعْلَمٌ - مَعْلَمٌ - مِعْلَمٌ","عَلِمَ - يَعْلِمُ - عِلْمًا - فَهُوَ عَالِمٌ - وَذَاكَ مَعْلُومٌ - اِعْلِمْ - لَا تَعْلِمْ - مَعْلِمٌ - مَعْلِمٌ - مِعْلَمٌ","عَلِمَ - يَعْلَمُ - عَالِمًا - فَهُوَ مَعْلُومٌ - وَذَاكَ عَالِمٌ - أُعْلُمْ - لَا تَعْلَمْ - مَعْلَمٌ - مَعْلَمٌ - مِعْلَمٌ","عَلَمَ - يَعْلُمُ - عِلْمًا - فَهُوَ عَالِمٌ - وَذَاكَ مَعْلُومٌ - اِعْلَمْ - لَا تَعْلَمْ - مَعْلَمٌ - مَعْلَمٌ - مِعْلَمٌ"],"correct":"عَلِمَ - يَعْلَمُ - عِلْمًا - فَهُوَ عَالِمٌ - وَذَاكَ مَعْلُومٌ - اِعْلَمْ - لَا تَعْلَمْ - مَعْلَمٌ - مَعْلَمٌ - مِعْلَمٌ","explanation":"Susunan Tasrif Ishtilahi lengkap Bab 4 untuk عَلِمَ: Fi'il Madhi عَلِمَ, Mudhori' يَعْلَمُ, Masdar عِلْمًا, Isim Fa'il عَالِمٌ, Isim Maf'ul مَعْلُومٌ, Fi'il Amr اِعْلَمْ, Fi'il Nahi لَا تَعْلَمْ, Isim Zaman/Makan مَعْلَمٌ, dan Isim Alat مِعْلَمٌ."},"3":{"question":"Bagaimana bentuk Tasrif Lughawi Fi'il Madhi dari lafadz عَلِمَ ketika bertemu dhomir Antum (أَنْتُمْ)?","options":["عَلِمْتُمْ","عَلِمُوا","عَلِمْنَ","عَلِمْتُنَّ"],"correct":"عَلِمْتُمْ","explanation":"Untuk dhomir أَنْتُمْ, Fi'il Madhi عَلِمَ di-sukun-kan lam fi'il-nya (م) dan ditambahi dhomir rafa' mutaharrik Tum (تُمْ), menjadi عَلِمْتُمْ."},"4":{"question":"Bagaimana bentuk Tasrif Lughawi Fi'il Mudhori' dari lafadz عَلِمَ ketika bertemu dhomir Hum (هُمْ)?","options":["يَعْلَمُونَ","تَعْلَمُونَ","يَعْلَمَانِ","يَعْلَمْنَ"],"correct":"يَعْلَمُونَ","explanation":"Untuk dhomir هُمْ, Fi'il Mudhori' يَعْلَمُ diawali Ya' mudhoro'ah dan diakhiri Wawu Jama' serta Nun Tsubut (علامة الرفع), menjadi يَعْلَمُونَ."},"5":{"question":"Bagaimana pengaruh Bina' Shahih Salim pada pola tasrifan lafadz عَلِمَ?","options":["Seluruh huruf asal (ع, ل, م) terbebas dari huruf 'illat, hamzah, dan tadh'if sehingga seluruh susunan tasrifannya utuh tanpa perubahan i'lal maupun idgham","Terjadi pembuangan 'ain fi'il saat bersambung dhomir mutaharrik","Huruf lam fi'il di-sukun-kan dan diganti huruf 'illat","Terjadi penggabungan dua huruf sejenis pada bentuk mudhori'"],"correct":"Seluruh huruf asal (ع, ل, م) terbebas dari huruf 'illat, hamzah, dan tadh'if sehingga seluruh susunan tasrifannya utuh tanpa perubahan i'lal maupun idgham","explanation":"Bina' Shahih Salim pada lafadz عَلِمَ membuat seluruh konjugasi tasrifan berjalan sesuai pola asal wazan tanpa mengalami gugur huruf, pergantian, atau peleburan."},"6":{"question":"Apa bentuk Fi'il Amr dan Fi'il Nahi dari lafadz عَلِمَ?","options":["اِعْلَمْ dan لَا تَعْلَمْ","اِعْلِمْ dan لَا تَعْلِمْ","أُعْلُمْ dan لَا تَعْلُمْ","عَلِّمْ dan لَا تُعَلِّمْ"],"correct":"اِعْلَمْ dan لَا تَعْلَمْ","explanation":"Fi'il Amr dibentuk dari mudhori' majzum تَعْلَمْ. Buang huruf mudhoro'ah dan tambahkan Hamzah Washol berharakat kasrah (karena 'ain fi'il di-fathah-kan) menjadi اِعْلَمْ. Nahinya لَا تَعْلَمْ."},"7":{"question":"Apa bentuk Isim Fa'il dan Isim Maf'ul dari lafadz عَلِمَ?","options":["عَالِمٌ dan مَعْلُومٌ","مُعْلِمٌ dan مُعْلَمٌ","عَلِيمٌ dan مَعْلَمٌ","عَالِمٌ dan مُعَلَّمٌ"],"correct":"عَالِمٌ dan مَعْلُومٌ","explanation":"Isim Fa'il dari Thulathi Mujarrad mengikuti wazan فَاعِلٌ menjadi عَالِمٌ, sedangkan Isim Maf'ul mengikuti wazan مَفْعُولٌ menjadi مَعْلُومٌ."},"8":{"question":"Bagaimana bentuk Fi'il Mabni Majhul (pasif) dari lafadz عَلِمَ dalam Fi'il Madhi dan Fi'il Mudhori'?","options":["عُلِمَ (Madhi) dan يُعْلَمُ (Mudhori')","عَلِمَ (Madhi) dan يَعْلَمُ (Mudhori')","عُلِمَ (Madhi) dan يُعْلِمُ (Mudhori')","عُلِّمَ (Madhi) dan يُعَلَّمُ (Mudhori')"],"correct":"عُلِمَ (Madhi) dan يُعْلَمُ (Mudhori')","explanation":"Madhi Majhul: huruf awal di-dhommah dan sebelum akhir di-kasrah (عُلِمَ). Mudhori' Majhul: huruf mudhoro'ah di-dhommah dan sebelum akhir di-fathah (يُعْلَمُ)."}}}]},{"id_kalimat":"amogenz_tasrif_011","teks_kalimat":"وَقَى","analysis":[{"id_lafadz":"amogenz_lafadz_011","word":"وَقَى","steps":{"1":{"question":"Apa Wazan asli dan Bab dari lafadz وَقَى dalam Tasrif Ishtilahi?","options":["Bab 2 (فَعَلَ - يَفْعِلُ) dengan wazan asal وَقَيَ - يَوْقِيُ","Bab 1 (فَعَلَ - يَفْعُلُ) dengan wazan asal وَقَوَ - يَوْقُوُ","Bab 3 (فَعَلَ - يَفْعَلُ) dengan wazan asal وَقَيَ - يَوْقَيُ","Bab 4 (فَعِلَ - يَفْعَلُ) dengan wazan asal وَقِيَ - يَوْقَيُ"],"correct":"Bab 2 (فَعَلَ - يَفْعِلُ) dengan wazan asal وَقَيَ - يَوْقِيُ","explanation":"Lafadz وَقَى tergolong Bab 2 Thulathi Mujarrad. Bentuk dasarnya sebelum di-i'lal adalah وَقَيَ - يَوْقِيُ."},"2":{"question":"Bagaimana susunan lengkap Tasrif Ishtilahi dari lafadz وَقَى?","options":["وَقَى - يَقِي - وِقَايَةً - فَهُوَ وَاقٍ - وَذَاكَ مَوْقِيٌّ - قِ - لَا تَقِ - مَوْقًى - مَوْقًى - مِيقًى","وَقَى - يَوْقِي - وَقْيًا - فَهُوَ وَاقِيٌ - وَذَاكَ مَوْقُويٌ - اِوْقِ - لَا تَوْقِ - مَوْقَيٌ - مَوْقَيٌ - مِوْقَيٌ","وَقَى - يَقَى - وِقَايَةً - فَهُوَ وَاقٍ - وَذَاكَ مَوْقًى - قَ - لَا تَقَ - مَوْقًى - مَوْقًى - مِيقًى","وَقَيَ - يَقِيُ - وِقَايَةً - فَهُوَ مَوْقِيٌّ - وَذَاكَ وَاقٍ - قِ - لَا تَقِ - مَوْقًى - مَوْقًى - مِيقًى"],"correct":"وَقَى - يَقِي - وِقَايَةً - فَهُوَ وَاقٍ - وَذَاكَ مَوْقِيٌّ - قِ - لَا تَقِ - مَوْقًى - مَوْقًى - مِيقًى","explanation":"Susunan Ishtilahi ter-i'lal dari وَقَى: Madhi وَقَى, Mudhori' يَقِي, Masdar وِقَايَةً, Isim Fa'il وَاقٍ, Isim Maf'ul مَوْقِيٌّ, Amr قِ, Nahi لَا تَقِ, Zaman/Makan مَوْقًى, Isim Alat مِيقًى."},"3":{"question":"Bagaimana bentuk Tasrif Lughawi Fi'il Madhi dari lafadz وَقَى ketika bertemu dhomir Anta (أَنْتَ)?","options":["وَقَيْتَ","وَقَاتَ","وَقَوْتَ","قَيْتَ"],"correct":"وَقَيْتَ","explanation":"Saat Fi'il Madhi وَقَى bersambung dhomir rafa' mutaharrik Anta (أَنْتَ), Alif Maqshurah kembali ke asal harakat/bentuknya yaitu Ya' yang di-sukun-kan, menjadi وَقَيْتَ."},"4":{"question":"Bagaimana bentuk Tasrif Lughawi Fi'il Mudhori' dari lafadz وَقَى ketika bertemu dhomir Antum (أَنْتُمْ)?","options":["تَقُونَ","تَقِيُونَ","تَوْقِيُونَ","تَقَيُونَ"],"correct":"تَقُونَ","explanation":"Asalnya تَوْقِيُونَ -> Wawu dibuang (Mithal) jadi تَقِيُونَ -> dhommah Ya' dibuang (itsqal) dan Ya' dibuang karena iltiqa' sakinain dengan Wawu Jama' -> Qaf di-dhommah-kan agar sesuai Wawu, menjadi تَقُونَ."},"5":{"question":"Bagaimana pengaruh Bina' Lafif Mafruq pada pola tasrifan lafadz وَقَى?","options":["Memiliki dua huruf 'illat yang terpisah (Fa' fi'il Wawu dan Lam fi'il Ya'). Fa' fi'il dibuang pada mudhori' (seperti Mithal) dan Lam fi'il di-i'lal menjadi Alif/Ya' (seperti Naqish)","Kedua huruf 'illat berjejeran sehingga di-idgham-kan menjadi satu","Fa' fi'il dan Lam fi'il dibuang secara bersamaan pada bentuk Fi'il Madhi","Tidak mengalami proses I'lal pada bentuk Madhi maupun Mudhori'"],"correct":"Memiliki dua huruf 'illat yang terpisah (Fa' fi'il Wawu dan Lam fi'il Ya'). Fa' fi'il dibuang pada mudhori' (seperti Mithal) dan Lam fi'il di-i'lal menjadi Alif/Ya' (seperti Naqish)","explanation":"Bina' Lafif Mafruq menggabungkan kaidah Mithal Wawi (pembuangan Wawu pada mudhori' يَقِي) dan kaidah Naqish Ya'i (pergantian/pembuangan Ya' lam fi'il)."},"6":{"question":"Apa bentuk Fi'il Amr dan Fi'il Nahi dari lafadz وَقَى untuk dhomir Anta (أَنْتَ)?","options":["قِ dan لَا تَقِ","اِوَقِ dan لَا تَوْقِ","قِي dan لَا تَقِي","وَقِ dan لَا تَوَقِ"],"correct":"قِ dan لَا تَقِ","explanation":"Dari mudhori' تَقِي: huruf mudhoro'ah dibuang (Wawu fa' fi'il sudah terbuang) -> sisa Qaf dan Ya'. Dalam keadaan jazam Amr, Ya' lam fi'il dibuang -> tersisa satu huruf berharakat kasrah yaitu قِ. Nahinya لَا تَقِ."},"7":{"question":"Apa bentuk Isim Fa'il dan Isim Maf'ul dari lafadz وَقَى?","options":["وَاقٍ dan مَوْقِيٌّ","وَاقِيٌ dan مَوْقُويٌ","مَوْقٍ dan مَوْقًى","وَاقٍ dan مَوْقُوٌّ"],"correct":"وَاقٍ dan مَوْقِيٌّ","explanation":"Isim Fa'il asal وَاقِيٌ -> Ya' dibuang pada keadaan rafa'/jar menjadi وَاقٍ. Isim Maf'ul asal مَوْقُويٌ -> Wawu wazan diganti Ya' lalu di-idgham-kan menjadi مَوْقِيٌّ."},"8":{"question":"Bagaimana bentuk Fi'il Mabni Majhul (pasif) dari lafadz وَقَى dalam Fi'il Madhi dan Fi'il Mudhori'?","options":["وُقِيَ (Madhi) dan يُوقَى (Mudhori')","وُقَى (Madhi) dan يُقَى (Mudhori')","وُقِيَ (Madhi) dan يُقِي (Mudhori')","وُقِّيَ (Madhi) dan يُوَقَّى (Mudhori')"],"correct":"وُقِيَ (Madhi) dan يُوقَى (Mudhori')","explanation":"Madhi Majhul: وُقِيَ (kasrah sebelum akhir, Ya' nampak fathah). Mudhori' Majhul: يُوقَى (Wawu dikembalikan karena sebelum Wawu berharakat dhommah dan Lam fi'il diganti Alif Maqshurah karena berharakat setelah fathah)."},"9":{"question":"Mengapa Fi'il Amr dari lafadz وَقَى hanya terdiri dari satu huruf (قِ) dan bagaimana bentuk Isim Alat-nya?","options":["Terdiri dari satu huruf karena Fa' fi'il (Wawu) dibuang akibat kaidah Mithal dan Lam fi'il (Ya') dibuang akibat tanda Jazam; sedangkan Isim Alat-nya adalah مِيقًى (asal مِوْقَيٌ)","Terdiri dari satu huruf karena dibuang untuk takhfif semata; sedangkan Isim Alat-nya adalah مِقًى","Terdiri dari satu huruf karena gabungan dua idgham; sedangkan Isim Alat-nya adalah مَوْقِيٌّ","Terdiri dari satu huruf karena mengikuti wazan Bab 6; sedangkan Isim Alat-nya adalah مِوَقٍ"],"correct":"Terdiri dari satu huruf karena Fa' fi'il (Wawu) dibuang akibat kaidah Mithal dan Lam fi'il (Ya') dibuang akibat tanda Jazam; sedangkan Isim Alat-nya adalah مِيقًى (asal مِوْقَيٌ)","explanation":"Lafadz وَقَى kehilangan fa' fi'il-nya di mudhori' (تَقِي) dan kehilangan lam fi'il-nya saat jazam/amr (قِ). Isim Alat asal مِوْقَيٌ diubah Wawu-nya jadi Ya' (sesudah kasrah) dan Ya' lam fi'il diganti Alif Maqshurah menjadi مِيقًى."}}}]}];
